import React, { useState, useEffect } from 'react';
import axios from 'axios';
import ProductCard from '../components/ProductCard';
import { useAuth } from '../context/AuthContext';

const Home = () => {
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);
    const { user } = useAuth();

    useEffect(() => {
        const fetchProducts = async () => {
            try {
                const { data } = await axios.get('http://localhost:5000/api/products');
                setProducts(data);
                setLoading(false);
            } catch (error) {
                console.error("Fetch error:", error);
                setLoading(false);
            }
        };
        fetchProducts();
    }, []);

    const handlePurchase = async (product) => {
        if (!user) { alert("Please Sign In."); return; }
        try {
            const token = await user.getIdToken();
            const { data: order } = await axios.post('http://localhost:5000/api/payments/create-order',
                { amount: product.price }, { headers: { Authorization: `Bearer ${token}` } });

            const options = {
                key: "YOUR_RAZORPAY_KEY_ID",
                amount: order.amount,
                currency: "INR",
                name: "BINDASS!!",
                order_id: order.id,
                handler: async (res) => {
                    await axios.post('http://localhost:5000/api/payments/verify-payment', { ...res, orderDetails: { productId: product._id, price: product.price } },
                        { headers: { Authorization: `Bearer ${token}` } });
                    alert("Order Placed!");
                },
                theme: { color: "#10221c" }
            };
            new window.Razorpay(options).open();
        } catch (e) { console.error(e); }
    };

    if (loading) return <div className="p-20 text-center font-['Manrope'] uppercase tracking-widest text-xs">Curating Collection...</div>;

    return (
        <div className="font-['Manrope'] bg-white">
            {/* Promo Bar */}
            <div className="bg-white text-[#10221c] text-[10px] uppercase tracking-[0.2em] py-2 text-center font-bold border-b border-gray-100">
                Join the Club BINDASS!! for exclusive access
            </div>

            {/* Hero Section */}
            <section className="relative h-[80vh] w-full overflow-hidden bg-slate-900">
                <img src="https://images.unsplash.com/photo-1539106609271-92523d4439c2?auto=format&fit=crop&q=80&w=2000" className="w-full h-full object-cover opacity-80" alt="Hero" />
                <div className="absolute inset-0 flex flex-col justify-center px-12 lg:px-24 text-white">
                    <span className="uppercase tracking-[0.4em] text-xs font-bold mb-4">Summer 2026 Collection</span>
                    <h1 className="text-6xl md:text-8xl font-extrabold leading-tight mb-8">Modern<br />Elegance</h1>
                    <button className="bg-emerald-600 hover:bg-emerald-500 text-white w-fit px-12 py-4 font-bold uppercase text-xs tracking-widest transition-all rounded-sm">Explore Collection</button>
                </div>
            </section>

            {/* Product Grid */}
            <section className="max-w-7xl mx-auto px-6 py-24">
                <div className="flex justify-between items-end mb-12">
                    <div>
                        <span className="text-emerald-600 font-bold uppercase tracking-widest text-xs">Recently Added</span>
                        <h2 className="text-4xl font-extrabold mt-2">New Arrivals</h2>
                    </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
                    {products.map((product) => (
                        <ProductCard key={product._id} product={product} onBuy={() => handlePurchase(product)} />
                    ))}
                </div>
            </section>
        </div>
    );
};

export default Home;
